"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[78447],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>a});var i=n(36672);const t={},s=i.createContext(t);function o(e){const r=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),i.createElement(s.Provider,{value:r},e.children)}},13325:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>m,frontMatter:()=>o,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"2023/03/28","title":"2023-03-28","description":"Debat om Windows\' tabloidnyheder og dataindsamling","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/03/28.md","sourceDirName":"2023/03","slug":"/2023/03/28","permalink":"/da/2023/03/28","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/03/28.md","tags":[],"version":"current","frontMatter":{"localized_date":"28. marts 2023","top_news":"Debat om Windows\' tabloidnyheder og dataindsamling"},"sidebar":"defaultSidebar","previous":{"title":"2023-03-29","permalink":"/da/2023/03/29"},"next":{"title":"2023-03-27","permalink":"/da/2023/03/27"}}');var t=n(23420),s=n(3331);const o={localized_date:"28. marts 2023",top_news:"Debat om Windows' tabloidnyheder og dataindsamling"},a="2023-03-28",l={},d=[{value:"Debat om Windows&#39; tabloidnyheder og dataindsamling",id:"debat-om-windows-tabloidnyheder-og-dataindsamling",level:2},{value:"Kritikere smadrer Apples Icloud Keychain for begr\xe6nsninger og d\xe5rlig brugeroplevelse",id:"kritikere-smadrer-apples-icloud-keychain-for-begr\xe6nsninger-og-d\xe5rlig-brugeroplevelse",level:2},{value:"Eu overv\xe5gningsforslag kr\xe6nker privatlivets fred, bedre l\xf8sninger er n\xf8dvendige",id:"eu-overv\xe5gningsforslag-kr\xe6nker-privatlivets-fred-bedre-l\xf8sninger-er-n\xf8dvendige",level:2},{value:"Cftc sags\xf8ger Binance for ulovlig handel og virksomhedsunddragelse",id:"cftc-sags\xf8ger-binance-for-ulovlig-handel-og-virksomhedsunddragelse",level:2},{value:"Medarbejdernes brug af OpenAI&#39;s ChatGPT giver anledning til sikkerhedsproblemer.",id:"medarbejdernes-brug-af-openais-chatgpt-giver-anledning-til-sikkerhedsproblemer",level:2},{value:"AI Voice Cloning Tech v\xe6kker bekymring for misbrug og svindel",id:"ai-voice-cloning-tech-v\xe6kker-bekymring-for-misbrug-og-svindel",level:2},{value:"John Glenns kamera til 40 dollars revolutionerede rumfotografering.",id:"john-glenns-kamera-til-40-dollars-revolutionerede-rumfotografering",level:2},{value:"Udviklere diskuterer fordele og ulemper ved Svelte Framework",id:"udviklere-diskuterer-fordele-og-ulemper-ved-svelte-framework",level:2},{value:"Safari 16.4: Funktioner og blandede anmeldelser",id:"safari-164-funktioner-og-blandede-anmeldelser",level:2},{value:"Hn-brugere diskuterer alternativer til GitHub i forbindelse med afbrydelser",id:"hn-brugere-diskuterer-alternativer-til-github-i-forbindelse-med-afbrydelser",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"2023-03-28",children:"2023-03-28"})}),"\n",(0,t.jsx)(r.h2,{id:"debat-om-windows-tabloidnyheder-og-dataindsamling",children:"Debat om Windows' tabloidnyheder og dataindsamling"}),"\n",(0,t.jsxs)(r.p,{children:["Kommentarer p\xe5 Hacker News diskuterer den praksis, hvor Windows viser tabloid-nyheder og push-notifikationer, hvor nogle kritiserer styresystemet for at afvige fra dets kerneform\xe5l, mens andre p\xe5peger, at funktionen har til form\xe5l at tjene Microsofts forretningsinteresser ved at indsamle brugerdata til m\xe5lrettede reklamer. Brugerne udtrykker deres forskellige erfaringer og pr\xe6ferencer med forskellige styresystemer, herunder Windows, Ubuntu og macOS, og diskuterer emner som stabilitet, hardwarekompatibilitet og den indl\xe6ringskurve, der er forbundet med forskellige styresystemer. Diskussionen fremh\xe6ver den subjektive karakter af at v\xe6lge et styresystem, idet brugerne understreger vigtigheden af at finde et styresystem, der passer til deres behov og pr\xe6ferencer. Kommentatorerne deler deres erfaringer med at bruge propriet\xe6re videodrivere i Windows og Linux, hvor nogle foretr\xe6kker Windows p\xe5 grund af hardwareunderst\xf8ttelse og brugervenlighed, mens andre foretr\xe6kker Linux p\xe5 grund af dets p\xe5lidelighed og support fra f\xe6llesskabet. Brugere p\xe5peger, at Windows-opdatering kan for\xe5rsage problemer, f.eks. at systemet g\xe5r i stykker, at batterilevetiden p\xe5 b\xe6rbare computere reduceres, og at der opst\xe5r problemer med bootloaderen, mens Linux kan v\xe6re ustabilt p\xe5 grund af fejl i drivere og pakkeh\xe5ndtering. Brugerne foresl\xe5r forskellige m\xe5der at l\xf8se disse problemer p\xe5, herunder ved at bruge forskellige Linux-distributioner. Diskussionen drejer sig om Linux' kompatibilitet med pc-spil, hvor nogle h\xe6vder, at der er sket forbedringer i de seneste \xe5r, mens andre p\xe5peger huller i spilunderst\xf8ttelse og ydeevne, is\xe6r med hensyn til foranstaltninger til bek\xe6mpelse af snyd. Brugerne udtrykker frustration over u\xf8nskede funktioner og reklamer p\xe5 Windows og diskuterer forskellige m\xe5der at tilpasse og kontrollere deres operativsystemer p\xe5 eller skifte til Linux eller spillekonsoller. Debatten drejer sig ogs\xe5 om graden af Linux' kompatibilitet med pc-spil, med forskellige meninger om antallet af spil, der spiller godt p\xe5 Linux, og vigtigheden af at kunne spille AAA-multiplayer-spil online. Brugerne kritiserer Windows for deres distraherende tabloidnyheder af lav kvalitet, som skaber frustration, og diskuterer m\xe5der at deaktivere eller begr\xe6nse m\xe6ngden af trashede eller misvisende overskrifter p\xe5 widgets boardet p\xe5. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35323121",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://www.tomshardware.com/news/windows-keeps-feeding-tabloid-news",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"kritikere-smadrer-apples-icloud-keychain-for-begr\xe6nsninger-og-d\xe5rlig-brugeroplevelse",children:"Kritikere smadrer Apples Icloud Keychain for begr\xe6nsninger og d\xe5rlig brugeroplevelse"}),"\n",(0,t.jsxs)(r.p,{children:["Brugere kritiserer Apples iCloud Keychain for d\xe5rlig brugeroplevelse p\xe5 Windows og begr\xe6nsninger p\xe5 Mac, f.eks. at den er bundet til Safari og har sv\xe6rt ved at finde indstillingerne for passwords. Der rapporteres om manglende integration med Keychain og Apples v\xe6rkt\xf8jer til administration af adgangskoder p\xe5 Windows, og Passkeys anses for at tilbyde ringe forbedringer. Nogle brugere antyder, at manglen p\xe5 str\xf8mlinet adgangskodeh\xe5ndtering er en del af Apples strategi for at skubbe kunderne over i retning af at bruge deres egen adgangskodeh\xe5ndtering i Google Chrome. Apple kan have gavn af at l\xe6gge mere v\xe6gt p\xe5 et v\xe6rkt\xf8jss\xe6t p\xe5 tv\xe6rs af platforme for at st\xf8tte v\xe6ksten i tjenesterne. Alt i alt giver artiklen en blandet vurdering af Apples adgangskodeh\xe5ndteringssystem og dets kompatibilitet med andre browsere. Brugerne anbefaler alternative adgangskodeadministratorer som Bitwarden eller 1Password, der tilbyder mere robuste funktioner, herunder muligheden for at dele adgangskoder mellem familiemedlemmer. Brugerne fremh\xe6ver vigtigheden af god passwordhygiejne og fremh\xe6ver de praktiske og sikkerhedsm\xe6ssige fordele ved at bruge en passwordmanager. Nogle brugere foresl\xe5r, at Apple b\xf8r frigive en selvst\xe6ndig app til adgangskoder, som er tilg\xe6ngelig fra et ikon p\xe5 v\xe6rkt\xf8jslinjen i Safari og udstyret med en komplet brugergr\xe6nseflade. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35329950",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://cabel.com/2023/03/27/apple-passwords-deserve-an-app/",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"eu-overv\xe5gningsforslag-kr\xe6nker-privatlivets-fred-bedre-l\xf8sninger-er-n\xf8dvendige",children:"Eu overv\xe5gningsforslag kr\xe6nker privatlivets fred, bedre l\xf8sninger er n\xf8dvendige"}),"\n",(0,t.jsxs)(r.p,{children:['Et forslag fra en svensk VPN-udbyder, der vil tvinge politikere i EU-landene til at underkaste sig kontinuerlig lyd- og videooverv\xe5gning d\xf8gnet rundt, er ikke egnet til et demokratisk samfund og kr\xe6nker den enkeltes ret til privatlivets fred. EU b\xf8r se p\xe5 alternative foranstaltninger for at \xf8ge gennemsigtigheden og ansvarligheden, s\xe5som reformer af lobbyvirksomhed og udvidelse af adgangen til information, i stedet for at gennemf\xf8re ekstreme overv\xe5gningsforanstaltninger. Diskussionen omfatter den manglende tillid til politikere og behovet for mere gennemsigtighed i deres beslutningstagning, med forslag, der sp\xe6nder fra personlig kontrol til gennemf\xf8relse af systemer svarende til kodegennemgang. I artiklen diskuteres \xf8delagte regeringsprocesser med hensyn til informationsbehandling og foresl\xe5s l\xf8sninger s\xe5som st\xf8rre gennemsigtighed, intensiv overv\xe5gning af politikere og udst\xf8delse i athensk stil ved offentlig afstemning. EU\'s forslag om at forbyde end-to-end-kryptering og kr\xe6ve, at virksomheder skal scanne alt indhold for ulovligt materiale, kr\xe6nker if\xf8lge kritikerne privatlivets fred og ytringsfriheden. Begrebet "D\xf8ren i ansigtet" diskuteres i forbindelse med politiske forhandlinger og ekstremistiske politikforslags mulighed for at f\xe5 mere moderate forslag til at virke acceptable. Det demokratiske underskud i EU er et problem for nogle, idet der rejses bekymring over Europa-Kommissionens autokratiske karakter og udvandingen af demokratiet, n\xe5r v\xe6lgerkorpset bliver for stort og mangfoldigt. ',(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35321994",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://mullvad.net/en/chatcontrol",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"cftc-sags\xf8ger-binance-for-ulovlig-handel-og-virksomhedsunddragelse",children:"Cftc sags\xf8ger Binance for ulovlig handel og virksomhedsunddragelse"}),"\n",(0,t.jsxs)(r.p,{children:["e amerikanske Commodity Futures Trading Commission (CFTC) har sags\xf8gt Binance for at tillade amerikanske kunder at handle med digitale aktiver uden at registrere sig hos agenturet og for ulovlig handel og virksomhedsunddragelse. Binance skulle angiveligt have anvendt en kompleks virksomhedsstruktur ved navn \"Tai Chi\" for at unddrage sig amerikansk tilsyn. Binances administrerende direkt\xf8r ben\xe6gter p\xe5standene. Kommentatorer udtrykker skepsis over for CFTC's handlinger, og nogle kritiserer virksomhedens manglende overholdelse af lovgivningen om bek\xe6mpelse af hvidvaskning af penge. Sagen rejser sp\xf8rgsm\xe5l om tilsynsmyndighedernes motiver, og derfor er de fleste af reaktionerne p\xe5 Hacker News skeptisk kritiske over for CFTC's handlinger. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35327996",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://www.docdroid.net/60YAbCz/cftc-binance-pdf",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"medarbejdernes-brug-af-openais-chatgpt-giver-anledning-til-sikkerhedsproblemer",children:"Medarbejdernes brug af OpenAI's ChatGPT giver anledning til sikkerhedsproblemer."}),"\n",(0,t.jsxs)(r.p,{children:["Medarbejdere bruger OpenAI's ChatGPT p\xe5 trods af bekymringer om datasikkerheden, og nogle virksomheder begr\xe6nser brugen heraf, mens andre ikke g\xf8r det. Der er bekymring for, at AI-v\xe6rkt\xf8jet kan blive et m\xe5l for exploits, og balancen mellem produktivitet og risiko skal overvejes. Datal\xe6kage og risici for privatlivets fred er bekymringer i forbindelse med brugen af ChatGPT til virksomheds- og f\xf8lsomme oplysninger, og nogle foresl\xe5r, at der er behov for en privat version. Forbud mod smartphones i sikre omr\xe5der og de potentielle risici ved at bruge AI-v\xe6rkt\xf8jer som ChatGPT dr\xf8ftes, og der er behov for forsigtighed og databeskyttelsesforanstaltninger. Virksomhederne er begyndt at frar\xe5de medarbejderne at bruge generative AI-tjenester og foresl\xe5r fortrolighedsaftaler og politikker for at forhindre eksponering af data. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35330438",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://www.darkreading.com/risk/employees-feeding-sensitive-business-data-chatgpt-raising-security-fears",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"ai-voice-cloning-tech-v\xe6kker-bekymring-for-misbrug-og-svindel",children:"AI Voice Cloning Tech v\xe6kker bekymring for misbrug og svindel"}),"\n",(0,t.jsx)(r.p,{children:'Der er ved at blive udviklet en teknologi til kloning af AI-stemmer, som kan klone stemmer med kun f\xe5 sekunders lydindgang. Denne teknologi har legitime anvendelsesmuligheder, f.eks. til at skabe lydb\xf8ger, men giver anledning til bekymring med hensyn til misbrug til svindel og efterligning. Play.ht, en nystartet virksomhed, der tilbyder stemmekloneringstjenester, har inviteret offentligheden til gratis at pr\xf8ve en beta-version af sin teknologi. Play.ht h\xe6vder at have "mange foranstaltninger p\xe5 plads for at \xf8ge sikkerheden ved denne tjeneste" for at forhindre misbrug. Brugerne har diskuteret teknologiens potentielle anvendelser og konsekvenser, idet fortalerne roser teknologiens potentiale til gavn og kritikerne udtrykker bekymring for misbrug. Teknologien kan kr\xe6ve regulering for at forhindre ulovlige anvendelsestilf\xe6lde, herunder skabelse af deepfake-lyd til skadelige form\xe5l. Nogle h\xe6vder dog, at et forbud mod alle lovlige anvendelser ikke vil forhindre de ulovlige anvendelser, og at uddannelse kan v\xe6re n\xf8glen til at im\xf8deg\xe5 potentielle svindelnumre.'}),"\n",(0,t.jsx)(r.h2,{id:"john-glenns-kamera-til-40-dollars-revolutionerede-rumfotografering",children:"John Glenns kamera til 40 dollars revolutionerede rumfotografering."}),"\n",(0,t.jsxs)(r.p,{children:["John Glenns brug af et kamera til 40 dollars under sin kredsl\xf8b om jorden tvang NASA til at genoverveje fotografiets rolle i forbindelse med rummissioner. Artiklen omhandler de nyskabelser, som NASA foretog i Glenns kamera, herunder et pistolgreb og en kabeludl\xf8sningsmekanisme. Betydningen af kreativitet og billige l\xf8sninger inden for teknologiske omr\xe5der fremh\xe6ves i kommentarfeltet. Glenns kamera spillede en vigtig rolle i udformningen af fremtidens rumforskning og dannede grundlaget for rumfotografering. Historien understreger styrken af historiefort\xe6lling og vigtigheden af at fange og dele mindev\xe6rdige \xf8jeblikke, selv n\xe5r de ikke er det prim\xe6re fokus i et projekt. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35328368",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://petapixel.com/2023/03/23/how-john-glenns-40-camera-forced-nasa-to-rethink-space-missions/",children:"L\xe6s originalteksten"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"udviklere-diskuterer-fordele-og-ulemper-ved-svelte-framework",children:"Udviklere diskuterer fordele og ulemper ved Svelte Framework"}),"\n",(0,t.jsxs)(r.p,{children:["Svelte er en popul\xe6r webramme til opbygning af brugergr\xe6nseflader med en brugervenlig struktur, hurtig app-ydelse og observerede tilstandsmaskiner, men der er potentielle udfordringer, herunder en indl\xe6ringskurve med reaktive udsagn og potentiale for fejl i stor skala. Svelte anvender en compilerbaseret tilgang, der kan f\xf8re til yderligere effektiviseringer for udviklere med minimal boilerplate-kode og nem tilstandsh\xe5ndtering, med kritikpunkter vedr\xf8rende h\xe5ndtering af komplekse reaktive afh\xe6ngigheder. I kommentarerne sammenlignes Svelte med alternative frameworks som React og Vue, med ros for den enklere udvikleroplevelse og funktionalitet, mens der ogs\xe5 diskuteres vigtigheden af enkelhed og klarhed i koden, p\xe5lidelig dokumentation og v\xe6rkt\xf8j. Diskussionen er centreret omkring sammenligning af forskellige JavaScript-frameworks som React, Vue og Svelte, med kompromisser, der skal overvejes, og det er vigtigt at tr\xe6ffe et informeret valg. Brugerne finder Svelte behageligt at arbejde med, og det er velegnet til sm\xe5 og store virksomhedsprojekter, med potentielle udfordringer omkring Svelte's $-m\xe6rke og h\xe5ndtering af ikke-lokale effekter. Artiklen diskuterer forfatterens erfaringer med at bruge Svelte til at bygge en personlig RSS-l\xe6ser, og fremh\xe6ver fordelene ved Sveltes komponentformat, indbyggede stores og event dispatcher API, men n\xe6vner ogs\xe5 lavpunkter som de reaktive statements ($), await-blokke og indbyggede overgangs- og animations-API'er. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35324430",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://tyhopp.com/notes/thoughts-on-svelte",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"safari-164-funktioner-og-blandede-anmeldelser",children:"Safari 16.4: Funktioner og blandede anmeldelser"}),"\n",(0,t.jsxs)(r.p,{children:["Safari 16.4 bringer nye og forbedrede funktioner, men f\xe5r blandede anmeldelser fra brugerne, hvor nogle roser dens effektivitet, mens andre kritiserer dens mangel p\xe5 avancerede muligheder for reklameblokering og kompatibilitet med websteder og udvidelser. Opdateringen indeholder fejlrettelser, underst\xf8ttelse af Apples Global Relay-standard og Web Push-notifikationer samt FaceTime SharePlay og Apples ProRes-codec til iPhone 13 Pro og 13 Pro Max. Safari 16.4 tilf\xf8jer underst\xf8ttelse af videodelen af Web Codecs API, push-meddelelser til Progressive Web Apps (PWA'er) og iframe lazy loading, blandt andre forbedringer i CSS, media queries og Web API. Browseren introducerer ogs\xe5 forbedringer til sine udviklerv\xe6rkt\xf8jer, hvilket giver st\xf8rre fleksibilitet til at tilpasse udvidelser til blokering af indhold og tilbyder forbedret beskyttelse af privatlivets fred for brugere med Lockdown-tilstand. Mens nogle kritiserer den manglende underst\xf8ttelse af Fullscreen og Screen Orientation API, er andre bekymrede over dominansen af \xe9n browsermotor p\xe5 iOS. Alt i alt leverer Safari 16.4 forbedret st\xf8tte til udviklere og en mere sikker browseroplevelse for brugerne med sine mange fejlrettelser og finpudsningsopdateringer. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35329961",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://webkit.org/blog/13966/webkit-features-in-safari-16-4/",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,t.jsx)(r.h2,{id:"hn-brugere-diskuterer-alternativer-til-github-i-forbindelse-med-afbrydelser",children:"Hn-brugere diskuterer alternativer til GitHub i forbindelse med afbrydelser"}),"\n",(0,t.jsxs)(r.p,{children:["Brugere diskuterer alternativer til GitHub under nedbrud, herunder selvhostede muligheder som Gerrit, Gitea og CodeCommit. Der bliver fremsat legende kommentarer om, at Discussion Service er en sidste udvej til kontrol, og der bliver lavet vittigheder om at v\xe6re offline for at undg\xe5 at blive hacket. Brugerne foresl\xe5r et trafikoverv\xe5gningsikon p\xe5 hovedsiden for at angive, n\xe5r der er noget galt med GitHub, og nogle s\xe6tter sp\xf8rgsm\xe5lstegn ved effektiviteten af Gits fejlmeddelelser. Der foresl\xe5s alternativer til en Git remote, f.eks. at arbejde over e-mail via diffs eller at oprette et backup-system med separate git-instanser. Nogle spekulerer i, om de seneste udfald p\xe5 GitHub er relateret til \xe6ndringer efter Microsofts overtagelse, men andre anerkender udfordringerne ved hurtig udvikling. Brugerne h\xe5ndterer risikoen for nedetid ved at gemme deres kode p\xe5 harddiske, virksomhedens servere eller GitLab eller ved at bruge alternativer som f.eks. synkronisering af repos over lokal eller fjern SSH eller ved at bruge e-mail til at kommunikere commits. Der findes en liste over internationale telefonnumre, hvor man kan abonnere p\xe5 et h\xe6ndelsesh\xe5ndteringssystem, og hvor dataafgifterne g\xe6lder, og brugerne accepterer privatlivspolitikker og servicevilk\xe5r. ",(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35325709",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,t.jsx)(r.a,{href:"https://www.githubstatus.com/incidents/52z0j6phhnjs",children:"L\xe6s originaltekst"}),"."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);